// The app's entry point. `app.rs` is generated by nuclo-native-ts; `nuclo` is the runtime's
// backend-independent core, and `gtk_backend` shows it with GTK 4 and libadwaita. `native` is
// the app's own platform code (its native/linux/ folder), empty when it has none.

mod app;
mod gtk_backend;
mod native;
mod nuclo;

fn main() {
    gtk_backend::run(app::nuclo_main);
}
